class Caesar {

  public static String verschiebe(String text, int n) {
    String ergebnis = "";
    for (int i = 0; i < text.length(); i++) {
      char c = text.charAt(i);
      if (c >= 'a' && c <= 'z') {
        c = (char) ('a' + (c - 'a' + n) % 26);
      }
      ergebnis = ergebnis + c;
    }
    return ergebnis;
  }

  public static void main(String[] s) {
    System.out.println( verschiebe("abc xyz", 3) );
    System.out.println( verschiebe("hallo welt", 1) );
    System.out.println( verschiebe("java", 0) );
  }
}

