class Temperatur {
  public static final double ABSOLUTER_NULLPUNKT = -273.15;

  private double celsius;

  public Temperatur(double celsius) {
    this.celsius = celsius;
  }

  public double getCelsius() {
    return celsius;
  }

  public double getFahrenheit() {
    return celsius * 9 / 5 + 32;
  }

  public int getGanzzahlig() {
    return (int) celsius;
  }

  public boolean istUnterNullpunkt() {
    return celsius < ABSOLUTER_NULLPUNKT;
  }

  public static void main(String[] s) {
    Temperatur t = new Temperatur(21.7);
    System.out.println("Celsius: " + t.getCelsius());
    System.out.println("Fahrenheit: " + t.getFahrenheit());
    System.out.println("Ganzzahlig: " + t.getGanzzahlig());
    System.out.println("Unter Nullpunkt: " + t.istUnterNullpunkt());
    System.out.println("Nullpunkt: " + Temperatur.ABSOLUTER_NULLPUNKT);
  }
}

